'use strict';
// Tests for the stdin/stdout line protocol of the Node.js backend (nime).
// Run with: node --test tests/nimeServer.test.js   (from the node/ directory)
//
// The request/reply pairs come from the one shared wire fixture,
// tests/wire-fixtures.json, which every backend adapter's suite iterates:
// case request_before_init and case init_unknown_guid are EasyIME/PIME#937,
// case malformed_json is #936.
