const { test } = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const { spawn } = require('node:child_process');
const path = require('node:path');

const NODE_DIR = path.join(__dirname, '..');
const FIXTURE = JSON.parse(
  fs.readFileSync(path.join(NODE_DIR, '..', 'tests', 'wire-fixtures.json'), 'utf8'));
const CLIENT_ID = FIXTURE.clientId;
const GUID = FIXTURE.guid.node;
const DECLARED_KEYS = new Set(FIXTURE.replyKeys.concat(FIXTURE.extraKeys));

// Fills the fixture's guid sentinels with this adapter's own values, at every
// depth: a request is an object, so the walk has to descend into it.
function resolve(value) {
  if (value === '$guid') {
    return GUID;
  }
  if (value === '$unknownGuid') {
    return FIXTURE.unknownGuid;
  }
  if (Array.isArray(value)) {
    return value.map(resolve);
  }
  if (value && typeof value === 'object') {
    const out = {};
    for (const [key, item] of Object.entries(value)) {
      out[key] = resolve(item);
    }
    return out;
  }
  return value;
}

// The `return` key is a JSON boolean here and 1/0 in the go backend.
function fold(value) {
  if (value === true) {
    return 1;
  }
  if (value === false) {
    return 0;
  }
  return value;
}

// Starts server.js the way PIMELauncher does and returns a helper that sends
// one raw line and resolves with the parsed JSON of the next PIME_MSG reply.
function startBackend() {
  const child = spawn(process.execPath, ['server.js'], { cwd: NODE_DIR, stdio: ['pipe', 'pipe', 'ignore'] });
  let buf = '';
  let waiter = null;
  let exited = false;
  let seen = 0;
  child.stdout.on('data', (chunk) => {
    buf += chunk.toString('utf8');
    let i;
    while ((i = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, i).trim();
      buf = buf.slice(i + 1);
      if (line.startsWith('PIME_MSG|')) {
        seen += 1;
        if (waiter) {
          const w = waiter;
          waiter = null;
          w(JSON.parse(line.slice(line.indexOf('|', 'PIME_MSG|'.length) + 1)));
        }
      }
    }
  });
  child.on('exit', () => { exited = true; if (waiter) { const w = waiter; waiter = null; w(null); } });
  return {
    sendLine: (line) => new Promise((resolve_, reject) => {
      const timer = setTimeout(() => { waiter = null; reject(new Error(`no reply to: ${line}`)); }, 10000);
      waiter = (reply) => { clearTimeout(timer); resolve_(reply); };
      child.stdin.write(line + '\n');
    }),
    // A frame that must produce no reply at all: written without a waiter, so
    // the next awaited send still reads the following reply in order.
    writeQuiet: (line) => child.stdin.write(line + '\n'),
    send: function (clientId, msg) { return this.sendLine(`${clientId}|${JSON.stringify(msg)}`); },
    replies: () => seen,
    alive: () => !exited,
    stop: () => child.kill(),
  };
}

for (const fixtureCase of FIXTURE.cases) {
  test(`wire fixture: ${fixtureCase.name}`, async () => {
    const b = startBackend();
    const before = b.replies();
    try {
      for (const step of fixtureCase.steps) {
        if (step.reply === null) {
          b.writeQuiet(step.raw);
          continue;
        }
        const reply = 'raw' in step
          ? await b.sendLine(step.raw)
          : await b.send(CLIENT_ID, resolve(step.request));
        for (const [key, expected] of Object.entries(step.reply)) {
          assert.ok(key in reply, `${fixtureCase.name}: reply lacks ${key}`);
          assert.deepStrictEqual(fold(reply[key]), fold(expected),
            `${fixtureCase.name}: ${key}`);
        }
        for (const key of Object.keys(reply)) {
          assert.ok(DECLARED_KEYS.has(key), `${fixtureCase.name}: undeclared key ${key}`);
        }
      }
      // Steps whose reply is null contribute no line, so the counts must match.
      const expected = fixtureCase.steps.filter((step) => step.reply !== null).length;
      assert.strictEqual(b.replies() - before, expected, `${fixtureCase.name}: reply count`);
      assert.ok(b.alive(), `${fixtureCase.name}: backend must stay alive`);
    } finally {
      b.stop();
    }
  });
}
